    fn exhaustive(
        vectors: &[(u32, Vec<(u32, f32)>)],
        query: &[(u32, f32)],
        k: usize,
    ) -> Vec<(u32, f32)> {
        let mut scored: Vec<(u32, f32)> = vectors
            .iter()
            .map(|(offset, v)| {
                let score: f32 = query
                    .iter()
                    .map(|(qd, qv)| {
                        v.iter()
                            .find(|(vd, _)| vd == qd)
                            .map(|(_, vv)| qv * vv)
                            .unwrap_or(0.0)
                    })
                    .sum();
                (*offset, score)
            })
            .filter(|(_, s)| *s > 0.0)
            .collect();
        scored.sort_by(|a, b| b.1.total_cmp(&a.1).then(a.0.cmp(&b.0)));
        scored.truncate(k);
        scored
    }

